default:
@import "tailwindcss";
@import "../../deps/ledger_ui/assets/css/ledger_ui.css";

/* Tema padrão do Ledger: não precisa acrescentar nada. */

both:
@import "tailwindcss";
@import "../../deps/ledger_ui/assets/css/ledger_ui.css";

/* Cinza: Slate no lugar do cinza do Ledger */
@theme {
    --color-gray-50: var(--color-slate-50);
    --color-gray-100: var(--color-slate-100);
    --color-gray-200: var(--color-slate-200);
    --color-gray-300: var(--color-slate-300);
    --color-gray-400: var(--color-slate-400);
    --color-gray-500: var(--color-slate-500);
    --color-gray-600: var(--color-slate-600);
    --color-gray-700: var(--color-slate-700);
    --color-gray-800: var(--color-slate-800);
    --color-gray-900: var(--color-slate-900);
    --color-gray-950: var(--color-slate-950);
}

/* Destaque: Fuchsia */
@theme {
    --color-accent: var(--color-fuchsia-600);
    --color-accent-content: var(--color-fuchsia-600);
    --color-accent-foreground: var(--color-white);
}

@layer theme {
    [data-theme=dark] {
        --color-accent: var(--color-fuchsia-600);
        --color-accent-content: var(--color-fuchsia-400);
        --color-accent-foreground: var(--color-white);
    }
}

accent:
@import "tailwindcss";
@import "../../deps/ledger_ui/assets/css/ledger_ui.css";

/* Destaque: Amber */
@theme {
    --color-accent: var(--color-amber-400);
    --color-accent-content: var(--color-amber-600);
    --color-accent-foreground: var(--color-amber-950);
}

@layer theme {
    [data-theme=dark] {
        --color-accent: var(--color-amber-400);
        --color-accent-content: var(--color-amber-400);
        --color-accent-foreground: var(--color-amber-950);
    }
}

gray:
@import "tailwindcss";
@import "../../deps/ledger_ui/assets/css/ledger_ui.css";

/* Cinza: Zinc no lugar do cinza do Ledger */
